set -euo pipefail
R=/dataset/shaoshitong/search-r1-rl/cosearch
base64 -d > "$R/tools/five_iteration_job.py" <<'PYCODE'

PYCODE
test -f "$R/logs/hardware.ready"
test -f "$R/logs/runtime-assets.ready"
test -f "$R/logs/retrieval-comparison.finished"
test ! -d "$R/runs/cosearch-local-five-20261003"
